  BattleBayDeluxe.tournament_wrapped_campaign_info = true
  for _, name in ipairs({ "SetupParam", "OnSetupLayer" }) do
    local f = _G[name]
    if type(f) == "function" then
      _G[name] = function(...)
        return BattleBayDeluxe.tournament_with_campaign_info(f, ...)
      end
    end
  end
end

